package net.runelite.client.plugins.microbot.droefficientwalker.sailing.core;

import java.io.*;
import java.util.Base64;
import java.util.zip.GZIPInputStream;

/** Generated from the supplied ALPHA image. A routing hint, NEVER collision authority. */
final class SeaReferenceData {
    static final int WEST = 896, SOUTH = 2048, CELL = 4, WIDTH = 800, HEIGHT = 528;
    static final String IMAGE_SHA256 = "62647fd9cba0e77b29943917c9bbaef7ea04d966a44dde3ceb2deb22131a406f";
    private static final String[] DATA = {
        "",
        ""
    };
    static byte[] decode() {
        try (InputStream in = new GZIPInputStream(new ByteArrayInputStream(
                Base64.getDecoder().decode(String.join("", DATA))))) {
            byte[] data = in.readNBytes(WIDTH * HEIGHT + 1);
            if (data.length != WIDTH * HEIGHT) throw new IOException("Invalid reference map size");
            return data;
        } catch (IOException | IllegalArgumentException ex) {
            // A missing/corrupt hint must not bypass live collision checks.
            return new byte[WIDTH * HEIGHT];
        }
    }
    private SeaReferenceData() { }
}
